/**
 * Embedded RentMaikar Brand Assets for Backend Domain (staging.rentmaikar.com)
 * 
 * Pre-compiled base64 strings and buffers ensure that the RentMaikar logo
 * and browser tab icons are served with zero filesystem dependencies and
 * guaranteed 100% uptime across all Cloud Run and container environments.
 */

export const RENTMAIKAR_LOGO_BASE64 = "";
export const RENTMAIKAR_FAVICON_PNG_BASE64 = "";
export const RENTMAIKAR_FAVICON_ICO_BASE64 = "";
export const RENTMAIKAR_APPLE_ICON_BASE64 = "";

export const RENTMAIKAR_LOGO_DATA_URL = "data:image/jpeg;base64," + RENTMAIKAR_LOGO_BASE64;
export const RENTMAIKAR_FAVICON_PNG_DATA_URL = "data:image/png;base64," + RENTMAIKAR_FAVICON_PNG_BASE64;

export const RENTMAIKAR_LOGO_BUFFER = Buffer.from(RENTMAIKAR_LOGO_BASE64, "base64");
export const RENTMAIKAR_FAVICON_PNG_BUFFER = Buffer.from(RENTMAIKAR_FAVICON_PNG_BASE64, "base64");
export const RENTMAIKAR_FAVICON_ICO_BUFFER = Buffer.from(RENTMAIKAR_FAVICON_ICO_BASE64, "base64");
export const RENTMAIKAR_APPLE_ICON_BUFFER = Buffer.from(RENTMAIKAR_APPLE_ICON_BASE64, "base64");
